 * boundary condition is explicit in the type system. This relies on
 * <optional>, which is only available starting from C++17 and is not
 * included here, and the participant's build is only guaranteed C++11.
 */
std::optional<unsigned int> next_fresh_counter(unsigned int counter,
                                                bool have_used_max) {
    if (counter == 0xFFFFFFFFu && have_used_max) {
        return std::nullopt;
    }
    return counter;
}

