    static bool have_used_max = false;
    static bool exhausted = false;

    if (exhausted) {
        return -1;
    }

    std::optional<unsigned int> maybe_counter = next_fresh_counter(counter, have_used_max);
    if (!maybe_counter.has_value()) {
        exhausted = true;
        return -1;
    }

    unsigned char nonce_block[16];
    build_nonce_block(*maybe_counter, nonce_block);

    unsigned char keystream_block[16];
    unsigned int block_idx = 0;
