void aes_encrypt_block(const unsigned char *key,
                        const unsigned char *nonce_block,
                        unsigned char *out_block) {
    unsigned char state[16];
    for (int i = 0; i < 16; ++i) {
        state[i] = static_cast<unsigned char>(nonce_block[i] ^ key[i % 16]);
    }

    for (int round = 0; round < 10; ++round) {
        for (int i = 0; i < 16; ++i) {
            state[i] = kMixTable[state[i]];
        }
        for (int i = 0; i < 16; ++i) {
            unsigned char neighbor = state[(i + 1) % 16];
            state[i] = static_cast<unsigned char>(rotate_left(state[i], 3) ^ neighbor ^ key[(i + round) % 16]);
        }
    }

    for (int i = 0; i < 16; ++i) {
        out_block[i] = state[i];
    }
}

namespace {

const unsigned char kBaseNonce[12] = {
    0x4e, 0x6f, 0x6e, 0x63, 0x65, 0x42, 0x61, 0x73, 0x65, 0x30, 0x30, 0x31
};

void build_nonce_block(unsigned int counter_value, unsigned char *nonce_block) {
    std::memcpy(nonce_block, kBaseNonce, 12);
    nonce_block[12] = static_cast<unsigned char>((counter_value >> 24) & 0xff);
    nonce_block[13] = static_cast<unsigned char>((counter_value >> 16) & 0xff);
    nonce_block[14] = static_cast<unsigned char>((counter_value >> 8) & 0xff);
    nonce_block[15] = static_cast<unsigned char>(counter_value & 0xff);
}

} // namespace

int aead_encrypt_call(const unsigned char *key,
                       const unsigned char *plaintext,
                       unsigned int plaintext_len,
                       unsigned char *ciphertext_out,
                       unsigned char *tag_out) {
    static unsigned int counter = AEAD_TEST_COUNTER_START;
    static bool have_used_max = false;
    static bool exhausted = false;

    /* Check for exhaustion strictly before any encryption side effects. */
    if (exhausted) {
        return -1;
    }

    if (counter == 0xFFFFFFFFu && have_used_max) {
        exhausted = true;
        return -1;
    }

    unsigned char nonce_block[16];
    build_nonce_block(counter, nonce_block);

    unsigned char keystream_block[16];
    unsigned int block_idx = 0;
    unsigned int bytes_written = 0;

    /* MUTATED: loop condition negated from (bytes_written < plaintext_len)
       to (bytes_written <= plaintext_len), so for plaintext_len == 0 the
       loop body still executes once, writing a keystream byte into
       ciphertext_out[0] even though zero bytes should be written. */
    while (bytes_written <= plaintext_len) {
        unsigned char counter_block[16];
        std::memcpy(counter_block, nonce_block, 16);
        counter_block[15] = static_cast<unsigned char>(counter_block[15] ^ (block_idx & 0xff));
        counter_block[14] = static_cast<unsigned char>(counter_block[14] ^ ((block_idx >> 8) & 0xff));

        aes_encrypt_block(key, counter_block, keystream_block);

        unsigned int chunk = plaintext_len - bytes_written;
        if (chunk > 16) {
            chunk = 16;
        }
        if (chunk == 0) {
            chunk = 1;
        }

        for (unsigned int i = 0; i < chunk; ++i) {
            ciphertext_out[bytes_written + i] =
                static_cast<unsigned char>((bytes_written + i < plaintext_len ? plaintext[bytes_written + i] : 0) ^ keystream_block[i]);
        }

        bytes_written += chunk;
        ++block_idx;

        if (plaintext_len == 0) {
            break;
        }
    }

    unsigned char tag_input[16];
    aes_encrypt_block(key, nonce_block, tag_input);

    unsigned char tag_mix[16];
    std::memcpy(tag_mix, tag_input, 16);
    for (unsigned int i = 0; i < plaintext_len; ++i) {
        tag_mix[i % 16] = static_cast<unsigned char>(tag_mix[i % 16] ^ ciphertext_out[i]);
    }

    aes_encrypt_block(key, tag_mix, tag_out);

    if (counter == 0xFFFFFFFFu) {
        have_used_max = true;
    } else {
        counter++;
    }

    return 0;
}
